window.__POLYGON_SCRIPT_PARTS__ = window.__POLYGON_SCRIPT_PARTS__ || [];
window.__POLYGON_SCRIPT_PARTS__.push(">\n              <div class=\"section__head\">\n                <span class=\"section__title\">Дорожки</span>\n                <button class=\"small-button\" type=\"button\" data-action=\"add-track\">+ Дорожка</button>\n              </div>\n              <div class=\"section__body\">\n                <div class=\"track-empty\">Дорожек пока нет</div>\n              </div>\n            </section>\n            <section class=\"section\">\n              <div class=\"section__head\"><span class=\"section__title\">Инструменты карты</span></div>\n              <div class=\"section__body\">\n                <div class=\"button-row\">\n                  <button class=\"small-button\" type=\"button\" data-map-action=\"add-point\">Добавить точку</button>\n                  <button class=\"small-button\" type=\"button\" data-map-action=\"add-area\">Добавить область</button>\n                  <button class=\"small-button\" type=\"button\" data-map-action=\"add-target\">Выбрать цель</button>\n                </div>\n              </div>\n            </section>\n          </div>`;\n      }\n\n      function mapEditorTemplate() {\n        const subtabs = Object.entries(mapSubmodeNames).map(([key, label]) =>\n          `<button class=\"subtab-button ${state.mapSubmode === key ? 'is-active' : ''}\" type=\"button\" data-map-submode=\"${key}\">${label}</button>`\n        ).join('');\n\n        let body = '';\n        if (state.mapSubmode === 'field') {\n          body = `\n            <section class=\"section\">\n              <div class=\"section__head\"><span class=\"section__title\">Размер поля</span></div>\n              <div class=\"section__body\">\n                <div class=\"field-grid\">\n                  <div class=\"field\"><label for=\"mapWidth\">Ширина, м</label><input id=\"mapWidth\" type=\"number\" value=\"120\" min=\"10\"></div>\n                  <div class=\"field\"><label for=\"mapHeight\">Высота, м</label><input id=\"mapHeight\" type=\"number\" value=\"80\" min=\"10\"></div>\n                </div>\n                <div class=\"button-row\" style=\"margin-top:10px\"><button class=\"action-button\" type=\"button\" data-action=\"apply-map-size\">Применить</button></div>\n              </div>\n            </section>`;\n        } else {\n          body = `\n            <section class=\"section\">\n              <div class=\"section__head\"><span class=\"section__title\">${mapSubmodeNames[state.mapSubmode]}</span></div>\n              <div class=\"section__body\">\n                <div class=\"section__hint\">Состав инструментов этой подвкладки пока не определён.</div>\n                <div class=\"button-row\" style=\"margin-top:10px\"><button class=\"small-button\" type=\"button\" data-map-action=\"paint-${state.mapSubmode}\">Работать на карте</button></div>\n              </div>\n            </section>`;\n        }\n        return `<div class=\"subtabs\">${subtabs}</div><div class=\"panel-scroll\">${body}</div>`;\n      }\n\n      function unitEditorTemplate() {\n        const rows = state.units.map(unit => `\n          <button class=\"unit-row ${state.selectedUnitId === unit.id ? 'is-active' : ''}\" type=\"button\" data-select-unit=\"${unit.id}\">\n            <span class=\"unit-row__icon\">${escapeHtml(unit.short)}</span>\n            <span><span class=\"unit-row__name\">${escapeHtml(unit.name)}</span><span class=\"unit-row__meta\">${escapeHtml(unit.type)} · ${escapeHtml(unit.sideLabel)}</span></span>\n            <span class=\"unit-row__side\">›</span>\n          </button>`).join('');\n\n        return `\n          <div class=\"panel-scroll\">\n            <div class=\"mode-summary\">\n              <span class=\"mode-summary__badge\">Юниты</span>\n              <span>Создание и изменение юнита выполняется только в этом разделе.</span>\n            </div>\n            <section class=\"section\">\n              <div class=\"section__head\">\n                <span class=\"section__title\">Юниты эксперимента</span>\n                <button class=\"small-button\" type=\"button\" data-action=\"create-unit\">+ Создать</button>\n              </div>\n              <div class=\"section__body\"><div class=\"unit-list\">${rows}</div></div>\n            </section>\n            <section class=\"section\">\n              <div class=\"section__head\"><span class=\"section__title\">Редактор выбранного юнита</span></div>\n              <div class=\"section__body\">\n                <div class=\"section__hint\">Набор изменяемых параметров будет проработан отдельно.</div>\n                <div class=\"button-row\" style=\"margin-top:10px\">\n                  <button class=\"action-button\" type=\"button\" data-map-action=\"place-unit\">Разместить юнита</button>\n                </div>\n              </div>\n            </section>\n          </div>`;\n      }\n\n      function unresolvedTemplate(title) {\n        return `\n          <div class=\"empty-state\">\n            <div>\n              <div class=\"empty-state__icon\">◇</div>\n              <strong>${escapeHtml(title)}</strong>\n              <p>Содержимое раздела пока оставлено пустым.</p>\n            </div>\n          </div>`;\n      }\n\n      function renderWorkspace() {\n        const templates = {\n          'program': programTemplate,\n          'map-editor': mapEditorTemplate,\n          'unit-editor': unitEditorTemplate,\n          'series': () => unresolvedTemplate('Серия'),\n          'metrics': () => unresolvedTemplate('Метрики'),\n          'journal': () => unresolvedTemplate('Журнал')\n        };\n        els.leftPanelContent.innerHTML = templates[state.workspace]();\n      }\n\n      function renderUnits() {\n        els.unitLayer.innerHTML = state.units.map(unit => `\n          <button\n            class=\"unit-marker ${state.selectedUnitId === unit.id ? 'is-selected' : ''}\"\n            style=\"left:${unit.x}%;top:${unit.y}%;--heading:${unit.heading}deg\"\n            type=\"button\"\n            data-unit-id=\"${unit.id}\"\n            data-side=\"${unit.side}\"\n            aria-label=\"Выбрать юнита ${escapeHtml(unit.name)}\">\n            ${escapeHtml(unit.short)}\n            <span class=\"unit-label\">${escapeHtml(unit.name)}</span>\n          </button>`).join('');\n      }\n\n      function renderMarkers() {\n        els.markerLayer.innerHTML = state.experiment.markers.map(marker => `\n          <span class=\"map-marker map-marker--${marker.type}\" style=\"left:${marker.x}%;top:${marker.y}%\" title=\"${escapeHtml(marker.label)}\"></span>`\n        ).join('');\n      }\n\n      function selectedUnit() {\n        return state.units.find(unit => unit.id === state.selectedUnitId) || null;\n      }\n\n      function inspectorBody(unit) {\n        const blank = (title) => `\n          <div class=\"empty-state\">\n            <div>\n              <div class=\"empty-state__icon\">·</div>\n              <strong>${escapeHtml(title)}</strong>\n              <p>Подробное содержимое этой информационной вкладки пока не переносилось в прототип.</p>\n            </div>\n          </div>`;\n\n        if (state.inspector === 'info') {\n          return `\n            <div class=\"panel-scroll\">\n              <section class=\"section\">\n                <div class=\"section__head\"><span class=\"section__title\">Текущее состояние</span><span class=\"status-chip\">${escapeHtml(unit.state)}</span></div>\n                <div class=\"section__body\">\n                  <dl class=\"data-list\">\n                    <div class=\"data-row\"><dt>Сторона</dt><dd>${escapeHtml(unit.sideLabel)}</dd></div>\n                    <div class=\"data-row\"><dt>Тип</dt><dd>${escapeHtml(unit.type)}</dd></div>\n                    <div class=\"data-row\"><dt>Здоровье</dt><dd>${unit.health}%</dd></div>\n                    <div class=\"data-row\"><dt>Подавление</dt><dd>${unit.suppression}%</dd></div>\n                  </dl>\n                </div>\n              </section>\n              <div class=\"meter\"><div class=\"meter__head\"><span>Состояние</span><strong>${unit.health}%</strong></div><div class=\"meter__track\"><div class=\"meter__fill\" style=\"--value:${unit.health}%\"></div></div></div>\n              <div class=\"meter\"><div class=\"meter__head\"><span>Подавление</span><strong>${unit.suppression}%</strong></div><div class=\"meter__track\"><div class=\"meter__fill\" style=\"--value:${unit.suppression}%\"></div></div></div>\n            </div>`;\n        }\n        if (state.inspector === 'overview') return blank('Обзор');\n        if (state.inspector === 'memory') return blank('Память');\n        if (state.inspector === 'danger') return blank('Опасность');\n        if (state.inspector === 'stealth') return blank('Скрытность');\n        if (state.inspector === 'positions') return blank('Позиции');\n        if (state.inspector === 'weapon') {\n          return `\n            <div class=\"panel-scroll\">\n              <section class=\"section\">\n                <div class=\"section__head\"><span class=\"section__title\">Вооружение</span></div>\n                <div class=\"section__body\">\n                  <dl class=\"data-list\">\n                    <div class=\"data-row\"><dt>Оружие</dt><dd>${escapeHtml(unit.weapon)}</dd></div>\n                    <div class=\"data-row\"><dt>Боеприпасы</dt><dd>${unit.ammo}</dd></div>\n                  </dl>\n                </div>\n              </section>\n            </div>`;\n        }\n        return '';\n      }\n\n      function renderInspector() {\n        const unit = selectedUnit();\n        if (!unit) {\n          els.rightPanelTitle.textContent = 'Юнит не выбран';\n          els.rightPanelContent.innerHTML = `\n            <div class=\"empty-state inspector-empty\">\n              <div>\n                <div class=\"empty-state__icon\">◎</div>\n                <strong>Выберите юнита на карте</strong>\n                <p>Здесь появится информация о его состоянии. Хара");
